do $$declare definition text;begin select pg_get_functiondef('fonkora_private.checkout_quote(jsonb,uuid)'::regprocedure) into definition; if strpos(definition, 'count(distinct (x->>''kind'',x->>''id''))')=0 then raise exception 'Expected checkout validation missing'; end if; execute replace(definition,'count(distinct (x->>''kind'',x->>''id''))','count(distinct (x->>''kind'',(x->>''id'')::bigint))');end $$;
